PAGE = dict(
    slug='path3',
    title='Pane::path3',
    signature='Trace& Pane::path3(Series x, Series y, Series z)',
    intro="Adds a **line in three dimensions**: the points `(x[i], y[i], z[i])` joined in the order given. It is the three-dimensional [`trend`](trend.md), for a trajectory, a curve in space or a track. The three series have the same length, or any of them length 1.\n\nThe pane must be volumetric ([`pane3`](../studio/pane3.md)); a planar pane takes [`trend`](trend.md). The view of the path is set by the pane's [`lens`](lens.md).",
    parameters='**x**, **y**, **z** (`Series`-convertible)\n    The coordinates of the points. Equal lengths, or length 1.',
    returns='`Trace&`\n    The new trace.',
    examples=[
        dict(id='helix', text='A helix: 41 points along a turning path that rises. The points are joined in the order given.',
             code='auto fig = studio("path3_helix");\nauto& pane = fig.pane3("p");\nstd::vector<double> hx, hy, hz;\nfor (int i = 0; i <= 40; ++i) {\n  const double t = 0.25 * i;\n  hx.push_back(std::cos(t));\n  hy.push_back(std::sin(t));\n  hz.push_back(0.1 * t);\n}\npane.path3(hx, hy, hz);\nfig.save_svg("figure.svg");'),
        dict(id='broadcast', text='A single value is repeated: this path stays in the plane z = 0.5.',
             code='auto fig = studio("path3_broadcast");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{0, 1, 1, 0, 0}, std::vector<double>{0, 0, 1, 1, 0}, std::vector<double>{0.5});\nfig.save_svg("figure.svg");'),
        dict(id='two', text='Several paths on one pane, each with its own call and its own colour.',
             code='auto fig = studio("path3_two");\nauto& pane = fig.pane3("p");\nstd::vector<double> hx, hy, hz;\nfor (int i = 0; i <= 40; ++i) {\n  const double t = 0.25 * i;\n  hx.push_back(std::cos(t));\n  hy.push_back(std::sin(t));\n  hz.push_back(0.1 * t);\n}\npane.path3(hx, hy, hz).label("helix");\nstd::vector<double> sx, sy, sz;\nfor (std::size_t i = 0; i < hx.size(); ++i) { sx.push_back(0.5 * hx[i]); sy.push_back(0.5 * hy[i]); sz.push_back(hz[i]); }\npane.path3(sx, sy, sz).label("inner");\npane.legend(KeyPlace::NorthWest);\nfig.save_svg("figure.svg");'),
        dict(id='view', text="The view is the pane's [`lens`](lens.md). The same path seen from the side and from above.",
             code='auto fig = studio("path3_view");\nfig.mosaic(1, 2);\nstd::vector<double> hx, hy, hz;\nfor (int i = 0; i <= 40; ++i) {\n  const double t = 0.25 * i;\n  hx.push_back(std::cos(t));\n  hy.push_back(std::sin(t));\n  hz.push_back(0.1 * t);\n}\nauto& side = fig.pane3("side");\nside.path3(hx, hy, hz);\nside.lens().look(0.0, 5.0);\nauto& above = fig.pane3("above");\nabove.path3(hx, hy, hz);\nabove.lens().look(0.0, 85.0);\nfig.save_svg("figure.svg");'),
        dict(id='errors', text='Inputs that cannot be drawn are refused when the trace is added, and the message names the method and the problem. The pane keeps the traces it had.',
             code='auto report = [](const char* what, auto&& call) {\n  auto fig = studio("path3_errors");\n  auto& pane = fig.pane3("p");\n  try {\n    call(pane);\n    std::cout << what << ": accepted\\n";\n  } catch (const pluss::Error& e) {\n    std::cout << what << ": " << e.message() << "\\n";\n  }\n};\nreport("lengths differ", [](Pane& pane) { pane.path3(std::vector<double>{1, 2, 3}, std::vector<double>{1, 2, 3}, std::vector<double>{1, 2}); });\nauto fig = studio("path3_errors_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{0, 1}, std::vector<double>{0, 1}, std::vector<double>{0, 1});\nfig.save_svg("figure.svg");'),
        dict(id='wrong_pane', text='`path3` needs a volumetric pane. On a planar pane it throws at once, naming the kind it needs, and nothing is added.',
             code='auto fig = studio("path3_wrong_pane");\nauto& pane = fig.pane2("p");\ntry {\n  pane.path3(std::vector<double>{0, 1}, std::vector<double>{0, 1}, std::vector<double>{0, 1});\n} catch (const pluss::Error& e) {\n  std::cout << e.message() << "\\n";\n}\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Returns the new [`Trace&`](../trace/label.md); the reference stays valid for the life of the pane, and the style calls of the trace ([`label`](../trace/label.md), [`stroke`](../trace/stroke.md), [`width`](../trace/width.md), ...) chain off it.\n- The data is copied into the trace when it is added, so changing the vector afterwards does not change the figure.\n',
    see=['[`Pane::trend`](trend.md): the line in a plane.', '[`Pane::cloud3`](cloud3.md): points in space.', '[`Pane::lens`](lens.md): the view.'],
)
